SELECT id, position, project, content, type, level, status,
       longitude, latitude, start_time, over_time, stay_time,
       create_time, update_time
FROM warning_information


        AND position LIKE CONCAT('%', #{query.position}, '%')


        AND status = #{query.status}


        AND level = #{query.level}


        AND type = #{query.type}


        AND start_time BETWEEN #{query.startTime} AND #{query.endTime}


ORDER BY start_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM warning_information


        AND position LIKE CONCAT('%', #{query.position}, '%')


        AND status = #{query.status}


        AND level = #{query.level}


        AND type = #{query.type}


        AND start_time BETWEEN #{query.startTime} AND #{query.endTime}
